arguments.command:
cat > tests/book_test.sh <<'EOF'
#!/bin/bash
fail=0
f=$(mktemp)
out=$(BOOKINGS=$f bash bin/book A 0900 1000 standup)
[ "$out" = "booked A 0900-1000" ] || { echo "book output"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "book appends"; fail=1; }
rm -f "$f"

# ROOM-12: overlap rejection
f=$(mktemp)
BOOKINGS=$f bash bin/book A 0900 1000 standup >/dev/null
before=$(cat "$f")
for t in "0930 1030" "0800 0930" "0900 1000" "0830 1100" "0930 0945"; do
  set -- $t
  if BOOKINGS=$f bash bin/book A $1 $2 x >/dev/null 2>&1; then echo "overlap $t accepted"; fail=1; fi
  [ "$(cat "$f")" = "$before" ] || { echo "file changed on overlap $t"; fail=1; }
done
BOOKINGS=$f bash bin/book A 1000 1100 next >/dev/null 2>&1 || { echo "adjacent after end rejected"; fail=1; }
BOOKINGS=$f bash bin/book A 0800 0900 prev >/dev/null 2>&1 || { echo "adjacent before start rejected"; fail=1; }
BOOKINGS=$f bash bin/book B 0900 1000 other >/dev/null 2>&1 || { echo "other room rejected"; fail=1; }
[ "$(wc -l < "$f")" -eq 4 ] || { echo "line count"; fail=1; }
rm -f "$f"
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?

